hooks.command:
python3 -c "import json,os,re,sys
d=json.load(sys.stdin)
cmd=str(d.get('tool_input',d).get('command','')).lower()
tokens=set(re.split(r'[^a-z0-9._/-]+',cmd))
search={'grep','egrep','fgrep','zgrep','rg','ripgrep','ack','ag'}
findbin={'find','fd'}
findflag={'-name','-iname','-regex','-path'}
exclude=('node_modules','package.json','package-lock.json','yarn.lock','pnpm-lock.yaml','.git/','graphify-out/','dist/','build/','coverage/','.venv','__pycache__')
hit=(bool(tokens&search) or (bool(tokens&findbin) and bool(tokens&findflag))) and not any(e in cmd for e in exclude) and os.path.isfile('graphify-out/graph.json')
if hit:
    print(json.dumps({'hookSpecificOutput':{'hookEventName':'PreToolUse','additionalContext':'MANDATORY: graphify-out/graph.json exists. You MUST run graphify query <question> before grepping raw source files. Only grep after graphify has oriented you, or to modify/debug specific lines. (Skipped for lockfiles/manifests, node_modules, VCS metadata, and build/coverage output.)'}}))" 2>/dev/null || true
